%[text] %[text:anchor:H_5DDECED0] ## Operating on Strings
%[text] %[text:anchor:H_7A1B9CDF] ### Formatting Strings for Consistency
%[text] ![](text:image:82e3) **Try**. Run this section, then change the value of `phrase` and rerun this section. 
phrase = "`Twas BRILLIG and the sLiThY toves..."
upper(phrase)
lower(phrase)
reverse(phrase)
out = split(phrase," ");
sort(out)
out = split(lower(phrase)," ");
sort(out)
%[text] ![](text:image:88fe) **Reflect**.
%[text] 1. Can you tell what the commands `upper`, `lower`, `reverse`, `split`, and `sort` do? Check the documentation on `sort` to see if you were correct.   \
%[text] ![](text:image:5d9c) **Try**. Sort `phrase` word by word in reverse alphabetical order.

%%
%[text] %[text:anchor:H_6CFAC968] ### Formatting Numeric Data as a String
%[text] You are likely to encounter situations where you want to present numeric data as a string, perhaps as human-readable output from a program, or to create a label for a plot. Using formatting commands to control how such a value is displayed can be helpful.  
%[text] %[text:anchor:H_449C45C7] #### Using `sprintf`
% Choosing the number of digits after the decimal place
A = sqrt(2)*ones(1,3);
txt = sprintf("Building up the square root of 2: \n| %.2f      |\n| %.3f     |\n| %.4f... |", A)
%[text] %[text:anchor:H_3983F205] #### Using `compose`
% Embedding dynamic values into a string

options = ["SI" "US"];
chooseUnits = options(1); %[control:dropdown:5b6d]{"position":[15,25]}

% Using symbolic units, calculate the acceleration due to gravity
% on Earth in the chosen unit system
u = symunit;
g = 9.80665*u.m/(u.s)^2;
g = unitConvert(g,chooseUnits);
[g0,units] = separateUnits(g);
g0 = double(g0);

% Create string labels for the units in SI and US systems
unitStr = ["m/s^2" "ft/s^2"];
myUnitLabel = unitStr(chooseUnits==options);

% Build the format string and compose it with the calculated values
fmtStr = "A rough approximation of g is %.0f.\n" + ...
    "A standard approximation is %.3g %s, \n\tbut " + ...
    "the exact standard value of g0 is %f %s. \n" + ...
    "Exactly 5 decimal places of pi are %.5f.";
str = compose(fmtStr,[g0 g0 myUnitLabel g0 myUnitLabel pi])
%[text] Such format strings can be particularly helpful in tracking the precision of your calculation so that you know that trailing zeros matter. Check out the [documentation on formatting text](https://www.mathworks.com/help/matlab/matlab_prog/formatting-strings.html) for more information.
%%
%[text] ![](text:image:6e51) **Exercise 1**. 
%[text] The matrix `genData` contains solar power generation data in kilowatts in five minute increments. The columns correspond to March 15-20, 2021. Use string formatting to create a descriptive title for the plot. Your title should include both the selected day and the total energy generated to the nearest tenth of a megawatt-hr, e.g., "On March 16, the solar array generated 2.7 Mwh".
load genData.mat genData
days = string(15:20);
col = days(1); %[control:dropdown:0e2e]{"position":[7,14]}
tot = createEnergyPlot(genData, days, col);
title("Descriptive Title, Please");
%%
%[text] %[text:anchor:H_BAC16BBF] ### Slicing up a String
%[text] Sometimes there will be a string you want to modify or where you only care about part of the information. 
sentence = "The quick brown fox jumps 3.14' over the lazy dog.";
replaceBetween(sentence,"The","brown"," slow ")
replace(sentence,"3.14","1.25")
extractBetween(sentence,"o","o")
extractAfter(sentence,"fox")
%%
%[text] ![](text:image:3348) **Exercise 2**.
%[text] Run the following code to generate sentences including a randomly chosen month and day. Write code that will extract the month from `sentence` as a string into the variable `month`. Be sure to get only the name of the month and no extra spaces or punctuation. Test your code by running it repeatedly. 
sentence = generateSentence

%%
%[text] %[text:anchor:H_C5377AFF] ## Further Explorations
%[text] Sometimes you may not know exactly what is coming before or after a piece of a string you care about, but you know the general [pattern](https://www.mathworks.com/help/matlab/ref/pattern.html) you are looking for. In this case, you want to describe the pattern and pull out information based on that pattern. Another common term for such pattern matching in code is [regular expressions](https://www.mathworks.com/help/matlab/ref/regexp.html).
%%
%[text] [⇦ Main Menu](file:../MainMenu.m)
%%
%[text] %[text:anchor:H_672AA15A] ## Helper Functions
function str = generateSentence
% generateSentence creates a sentence with a standard structure containing
% a randomly chosen month and day
day = randi(29);
month = randi(12);
months = ["January" "February" "March" "April" "May" "June" ...
    "July" "August" "September" "October" "November" "December"];
str = "It is " + months(month) + " " + day + ", and all is well.";
end

function tot = createEnergyPlot(genData, days, dayChoice)
% createEnergyPlot creates a plot of the generation data and cumulative
% energy generated on dayChoice; it returns the total energy generated
% on dayChoice in kwh

% Compute the total energy generated in kwh as a function of time
tot = cumtrapz(genData(:,days==dayChoice)/60);
% Set up a vector of times
t = 0:1/60:24-1/60;
yyaxis left
plot(t,genData(:,days==dayChoice))
ylabel("kw")
yyaxis right
plot(t,tot)
ylabel("kwh")
xlabel("Time in hours")
xlim([0 24])
tot = tot(end);
end
